create schema if not exists ged;
create extension if not exists pgcrypto;
create table if not exists ged.document_ai_analysis (id uuid primary key default gen_random_uuid(),tenant_id uuid not null,document_id uuid not null,analysis_status varchar(40) not null default 'PENDING',analysis_source varchar(40) not null default 'LOCAL_RULES',extracted_text text,extracted_summary text,detected_document_type text,detected_subject text,detected_date date,detected_people jsonb,detected_identifiers jsonb,detected_sensitive_data jsonb,confidence numeric(5,2) not null default 0,error_message text,analyzed_at timestamptz,created_at timestamptz not null default now(),reg_status char(1) not null default 'A');
create table if not exists ged.document_classification_suggestion (id uuid primary key default gen_random_uuid(),tenant_id uuid not null,document_id uuid not null,analysis_id uuid references ged.document_ai_analysis(id),suggested_classification_id uuid,suggested_classification_code text,suggested_classification_title text,suggested_reason text,confidence numeric(5,2) not null default 0,status varchar(40) not null default 'PENDING',reviewed_by uuid,reviewed_at timestamptz,review_notes text,created_at timestamptz not null default now(),reg_status char(1) not null default 'A');
create table if not exists ged.document_retention_suggestion (id uuid primary key default gen_random_uuid(),tenant_id uuid not null,document_id uuid not null,analysis_id uuid references ged.document_ai_analysis(id),suggested_rule_id uuid,suggested_phase text,suggested_final_destination text,suggested_trigger_event text,suggested_retention_until date,suggested_reason text,confidence numeric(5,2) not null default 0,status varchar(40) not null default 'PENDING',reviewed_by uuid,reviewed_at timestamptz,review_notes text,created_at timestamptz not null default now(),reg_status char(1) not null default 'A');
create table if not exists ged.document_quality_issue (id uuid primary key default gen_random_uuid(),tenant_id uuid not null,document_id uuid not null,issue_type varchar(80) not null,severity varchar(30) not null default 'MEDIUM',title text not null,description text,recommended_action text,status varchar(40) not null default 'OPEN',resolved_by uuid,resolved_at timestamptz,created_at timestamptz not null default now(),reg_status char(1) not null default 'A');
create table if not exists ged.smart_search_query_log (id uuid primary key default gen_random_uuid(),tenant_id uuid,user_id uuid,query_text text not null,normalized_query text,result_count integer not null default 0,execution_ms integer,searched_at timestamptz not null default now(),payload_json jsonb,reg_status char(1) not null default 'A');
create index if not exists ix_document_ai_analysis_document on ged.document_ai_analysis(tenant_id,document_id,created_at desc);
create index if not exists ix_document_classification_suggestion_status on ged.document_classification_suggestion(tenant_id,status,confidence desc);
create index if not exists ix_document_retention_suggestion_status on ged.document_retention_suggestion(tenant_id,status,confidence desc);
create index if not exists ix_document_quality_issue_status on ged.document_quality_issue(tenant_id,status,severity);
create index if not exists ix_smart_search_query_log_tenant_date on ged.smart_search_query_log(tenant_id,searched_at desc);
